import xmltodict
from taf.ul.auto_commissioning.utils import assure_is_list


class ManagedObjectDictsFromSCF:

    def get(self, scf_addr):
        """Gives Ordered Dicts for managed objects for given SCF file"""
        return assure_is_list(self.get_managed_objects(self.parse_xml(self.get_xml_str(scf_addr))))

    @staticmethod
    def get_xml_str(addr):
        with open(addr) as xml_file:
            return xml_file.read()

    @staticmethod
    def parse_xml(xml_str):
        return xmltodict.parse(xml_str)

    @staticmethod
    def get_managed_objects(xml):
        return xml["raml"]["cmData"]["managedObject"]
